// Read-only probe: Data API row counts per role, plus non-mutating write probes.
const URL_ = 'http://127.0.0.1:54321'
const KEY = 'sb_publishable_ACJWlzQHlZjBrEguHvfOxg_3BJgxAaH'
const PW = 'RentDemo#2026'
const users = ['manager@northwind.test', 'staff@northwind.test', 'aisyah@northwind.test', 'ben@northwind.test', 'probe@northwind.test', 'manager@beta.test', 'chen@beta.test']
const tables = ['organizations', 'memberships', 'units', 'tenants', 'leases', 'invoices', 'payments', 'payment_allocations', 'gateway_bills', 'audit_log']

async function login(email) {
  const r = await fetch(`${URL_}/auth/v1/token?grant_type=password`, {
    method: 'POST', headers: { apikey: KEY, 'content-type': 'application/json' }, body: JSON.stringify({ email, password: PW }),
  })
  const j = await r.json()
  return j.access_token
}

async function count(token, t) {
  const h = { apikey: KEY }
  if (token) h.authorization = `Bearer ${token}`
  const r = await fetch(`${URL_}/rest/v1/${t}?select=*`, { headers: h })
  const txt = await r.text()
  if (r.status !== 200) return `${r.status}`
  const rows = JSON.parse(txt)
  const orgs = new Set(rows.map((x) => x.org_id ?? x.id))
  return `${rows.length}(orgs:${orgs.size})`
}

async function noopWrites(token) {
  const h = { apikey: KEY, 'content-type': 'application/json', Prefer: 'return=representation' }
  if (token) h.authorization = `Bearer ${token}`
  const out = []
  for (const t of tables) {
    const p = await fetch(`${URL_}/rest/v1/${t}?id=eq.00000000-0000-0000-0000-000000000000`, { method: 'PATCH', headers: h, body: JSON.stringify({ created_at: '2020-01-01T00:00:00Z' }) })
    const d = await fetch(`${URL_}/rest/v1/${t}?id=eq.00000000-0000-0000-0000-000000000000`, { method: 'DELETE', headers: h })
    out.push(`${t}:P${p.status}/D${d.status}`)
  }
  return out.join(' ')
}

const anonLine = []
for (const t of tables) anonLine.push(`${t}=${await count(null, t)}`)
console.log('anon', anonLine.join(' '))
console.log('anon writes', await noopWrites(null))
for (const u of users) {
  const tok = await login(u)
  const line = []
  for (const t of tables) line.push(`${t}=${await count(tok, t)}`)
  console.log(u, line.join(' '))
  console.log('  writes', await noopWrites(tok))
  const rpc = await fetch(`${URL_}/rest/v1/rpc/is_org_member`, { method: 'POST', headers: { apikey: KEY, authorization: `Bearer ${tok}`, 'content-type': 'application/json' }, body: '{}' })
  console.log('  rpc', rpc.status)
}

